package com.medtrack.batch.dto; import com.medtrack.batch.entity.Batch; import java.time.LocalDate; import java.util.UUID; public record BatchResponse(UUID id,String batchNumber,UUID medicineId,UUID supplierId,LocalDate manufacturingDate,LocalDate expiryDate,int initialQuantity,String status){public static BatchResponse of(Batch b){return new BatchResponse(b.getId(),b.getBatchNumber(),b.getMedicine().getId(),b.getSupplier().getId(),b.getManufacturingDate(),b.getExpiryDate(),b.getInitialQuantity(),b.getStatus().name());}}
